package cli

// Core catalogs are fixed text, never AI-generated at runtime. Missing entries
// deliberately fall back to English; stable codes and JSON enums are untouched.
func secondaryLanguageIndex(language string) int {
	switch language {
	case "de":
		return 0
	case "fr":
		return 1
	case "es":
		return 2
	case "pt-BR":
		return 3
	case "ja":
		return 4
	}
	return -1
}

